\begin{thm}
 Every linked system of quartet trees is definitive.
\label{hierarchy} 
\end{thm}

openai_raw_latex:
\begin{thm}
 Every linked system of quartet trees is definitive.
\label{hierarchy} \end{thm}

anthropic_raw_latex:
\begin{thm}
The minimal number $k(n)$ such that every collection of quartets $S$  with $|S| \geq k$ is decisive is greater than ${n \choose 4} - (n-3)$.
\label{ge}
\end{thm}

