\begin{theorem}  \label{mainreslt}
If any of the $m_{th}$-order squared matrices of  $A \in \mathbb{R}^{m \times n}$ is a normal matrix and in the class  $\mathbb{F}$, and also D-stable matrix,
then there exists a block diagonal non-square matrix $K \in \mathbb{C}^{n \times m}$ such that for all non-negative diagonal matrices $E \in  \mathbb{R}^{n \times n}$, and $j \in \mathcal{M}$, where $\mathcal{M}$ is the index set consisting of $k$ tuples of integers in the
range $1,\cdots, m$,
\begin{equation}\label{suf_con}
Re\{ \sigma_i ( [A E K]_j ) \} >0,
\end{equation}
where $\text{Re} \{ \sigma_i (M) \}$ represents the real part of the $i$-th eigenvalue of matrix $M$.
\end{theorem}

